다음 C 프로그램의 출력 결과는?

int s = 0;
for (int i = 1; i <= 5; i++)
    s += i;
printf("%d", s);

다음 C 프로그램의 출력 결과는?

int a[5] = {1, 2, 3, 4, 5};
printf("%d", a[2]);

다음 자바 코드의 출력 결과는?

int x = 10;
x += 5;
x *= 2;
System.out.println(x);

다음 C 프로그램의 출력 결과는?

int i = 0, c = 0;
while (i < 10) {
    i += 3;
    c++;
}
printf("%d %d", i, c);

다음 C 프로그램의 출력 결과는?

int a = 5, b;
b = a++;
printf("%d %d", a, b);

다음 자바 코드의 출력 결과는?

int n = 2, s = 0;
switch (n) {
    case 1: s += 1;
    case 2: s += 2;
    case 3: s += 3; break;
    default: s += 10;
}
System.out.println(s);

다음 C 프로그램의 출력 결과는?

int a[3] = {10, 20, 30};
int *p = a;
printf("%d", *(p + 2) - *p);
